// Extension d'essai du lot 3 (protocole 1.0) : commandes déclarées, avis, saisie.
const textes = {
  fr: { posee: "Boîte posée.", annulee: "Saisie annulée : rien n'a été dessiné.", titre: "Dimensions de la boîte", largeur: "Largeur", profondeur: "Profondeur", hauteur: "Hauteur", forme: "Forme", pleine: "Pleine", base: "Base seule", grouper: "Grouper la boîte", nom: "Nom du groupe", defaut: "Boîte", faite: "Boîte dessinée : ", compte: " face(s), " , aretes: " arête(s), ", objets: " objet(s)." },
  en: { posee: "Box placed.", annulee: "Input cancelled: nothing was drawn.", titre: "Box dimensions", largeur: "Width", profondeur: "Depth", hauteur: "Height", forme: "Shape", pleine: "Solid", base: "Base only", grouper: "Group the box", nom: "Group name", defaut: "Box", faite: "Box drawn: ", compte: " face(s), ", aretes: " edge(s), ", objets: " object(s)." },
};
const t = (d) => textes[d && d.langue === "en" ? "en" : "fr"];

planche.sur("commande.poser-boite", async (d) => {
  await planche.operation.ouvrir("Poser une boîte");
  const elements = await planche.modele.boite([0, 0, 0], 1, 1, 1);
  const objet = await planche.modele.grouper(elements, t(d).defaut);
  await planche.selection.definir([objet]);
  await planche.operation.valider();
  await planche.message.afficher(t(d).posee);
  return objet;
});

planche.sur("commande.boite-sur-mesure", async (d) => {
  const x = t(d);
  const v = await planche.saisie.demander(x.titre, [
    { id: "nom", libelle: x.nom, genre: "texte", valeur: x.defaut },
    { id: "largeur", libelle: x.largeur, genre: "nombre", valeur: 2, min: 0.01, max: 100, unite: "m" },
    { id: "profondeur", libelle: x.profondeur, genre: "nombre", valeur: 1, min: 0.01, max: 100, unite: "m" },
    { id: "hauteur", libelle: x.hauteur, genre: "nombre", valeur: 0.5, min: 0.01, max: 100, unite: "m" },
    { id: "forme", libelle: x.forme, genre: "choix", valeur: "pleine", choix: [{ valeur: "pleine", libelle: x.pleine }, { valeur: "base", libelle: x.base }] },
    { id: "grouper", libelle: x.grouper, genre: "case", valeur: true },
  ]);
  if (v === null) {
    await planche.message.afficher(x.annulee, "alerte");
    return null;
  }
  const elements = v.forme === "pleine" ? await planche.modele.boite([3, 0, 0], v.largeur, v.profondeur, v.hauteur) : await planche.modele.rectangle([3, 0, 0], [v.largeur, 0, 0], [0, v.profondeur, 0]);
  if (v.grouper) await planche.selection.definir([await planche.modele.grouper(elements, v.nom || x.defaut)]);
  await planche.message.afficher(x.faite + v.largeur + " × " + v.profondeur + " × " + v.hauteur + " m");
  return v;
});

planche.sur("commande.compter", async (d) => {
  const m = await planche.modele.lire();
  await planche.message.afficher(m.faces.length + t(d).compte + m.aretes.length + t(d).aretes + m.objets.length + t(d).objets);
  return { faces: m.faces.length, aretes: m.aretes.length, objets: m.objets.length };
});

planche.sur("commande.trainer", async () => {
  await planche.modele.ligne([0, 0, 0], [7, 7, 7]);
  for (;;) {}
});

planche.sur("commande.echouer", async () => {
  await planche.modele.ligne([0, 0, 0], [9, 9, 9]);
  throw new Error("essai d'échec");
});
